+			kind: "max_tokens_recovery",
+			reason: "max_tokens_recovery",
+			iteration: this.state.iteration,
+		};
+		this.captureTaskLifecycle(TASK_MAX_TOKENS_RECOVERY_EVENT, {
+			phase: "started",
+		});
